mat2 rot(float a) { float s = sin(a), c = cos(a); return mat2(c, -s, s, c); }
float map(vec3 p) {
  p.z += time * 0.8;
  float g = dot(sin(p * 1.5), cos(p.zxy * 1.5)) - 0.2;
  float crystal = length(abs(mod(p, 2.0) - 1.0)) - 0.7;
  return max(g, -crystal);
}
shader_body {
  vec2 p = (uv - 0.5) * vec2(aspect.x, 1.0) * 2.0;
  vec3 ro = vec3(0.0, 0.0, -1.0);
  vec3 rd = normalize(vec3(p, 1.4));
  float t = 0.0;
  for (int i = 0; i < 48; i++) {
    float d = map(ro + rd * t);
    if (d < 0.003 || t > 12.0) break;
    t += d * 0.75;
  }
  vec3 col = vec3(0.04, 0.01, 0.08);
  if (t < 12.0) {
    vec3 pos = ro + rd * t;
    vec2 e = vec2(0.004, 0.0);
    vec3 n = normalize(vec3(
      map(pos + e.xyy) - map(pos - e.xyy),
      map(pos + e.yxy) - map(pos - e.yxy),
      map(pos + e.yyx) - map(pos - e.yyx)
    ));
    vec3 l = normalize(vec3(0.5, 1.0, -1.0));
    float diff = max(dot(n, l), 0.0);
    float spec = pow(max(dot(reflect(-l, n), -rd), 0.0), 32.0);
    float rim = pow(1.0 - max(dot(n, -rd), 0.0), 2.5);
    col = vec3(0.1, 0.02, 0.2) + diff * vec3(0.5, 0.1, 0.8) + spec * vec3(1.0, 0.8, 1.0) + rim * vec3(0.8, 0.3, 1.0);
  }
  ret = col;
}
